import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(old_limit)

    first = next((i for i, row in enumerate(records) if any(cell.strip() for cell in row)), None)
    if first is None:
        return {"columns": [], "rows": []}

    header_index = first
    if sum(bool(cell.strip()) for cell in records[first]) < 2:
        for i in range(first + 1, len(records)):
            if sum(bool(cell.strip()) for cell in records[i]) >= 2:
                header_index = i
                break

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max([len(columns)] + [len(row) for row in rows])

    existing = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "column_{}".format(number)
        while name in existing:
            number += 1
            name = "column_{}".format(number)
        columns.append(name)
        existing.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
